class FEMenu {
public:
    virtual void HighlightDefault();
    virtual void OnUnactivate(FEMenu *);
};

class IGOFrontEnd {
public:
    enum RUN_STATE { RUNSTATE_NORMAL };
    virtual void SetDisplay(bool);
    virtual RUN_STATE GetRunState();
    void ShowMenuBackground(bool);
};

class FEManager {
public:
    IGOFrontEnd *IGO;
    bool score_display;
};

class kellyslater_controller {
public:
    enum { SUPER_STATE_FLYBY };
    virtual int get_super_state();
};

class world_dynamics_system {
public:
    kellyslater_controller *get_ks_controller(int);
};

class game {
public:
    int get_active_player();
    int get_beach_id();
    int get_game_mode();
    void unpause();
};

class app {
public:
    static app *inst();
    game *get_game();
};

class FrontEndManager {
public:
    char pad[4];
};

extern FrontEndManager frontendmanager;
extern world_dynamics_system *g_world_ptr;
extern game *g_game_ptr;

enum {
    BEACH_INDOOR,
    GAME_MODE_CAREER
};

class LostControllerMenuClass {
    char pad[0x78];
public:
    bool draw;
    char pad79[3];
    int old_device_flags;
    int pause_controller;
    int pause_player;
    char pad88[4];
    bool replay_mode;
    char pad8d[3];
    int unused90;
    int active;
    FEManager *manager;
    FEMenu **menus;

    virtual void SetDeviceFlags(int);
    void OnStart(int);
};

void LostControllerMenuClass::OnStart(int c)
{
	int	i;

	if (!draw)
		return;

	// Reenable old devices when pause menu is cleared
	SetDeviceFlags( old_device_flags );
	pause_controller = -1;
	pause_player = -1;

	if (!replay_mode)
	{
		kellyslater_controller *	ksctrl = g_world_ptr->get_ks_controller(g_game_ptr->get_active_player());

		app::inst()->get_game()->unpause();

		if (g_game_ptr->get_beach_id() == BEACH_INDOOR && g_game_ptr->get_game_mode() == GAME_MODE_CAREER)
			manager->IGO->SetDisplay(true);
		else if (ksctrl->get_super_state() != kellyslater_controller::SUPER_STATE_FLYBY && manager->IGO->GetRunState() == IGOFrontEnd::RUNSTATE_NORMAL)
			manager->IGO->SetDisplay(manager->score_display);

		manager->IGO->ShowMenuBackground(false);
	}

	// Reset all menus' highlighted entries to defaults.
	for (i = 0; i < 24; i++)
		menus[i]->HighlightDefault();

	menus[active]->OnUnactivate(0);


	draw = false;
}
